#ifndef DSCO_SURFACE_REGISTRY_H
#define DSCO_SURFACE_REGISTRY_H
#include <stdbool.h>
#include <stddef.h>
#define SURFACE_DESCRIPTION "Manage a persistent owned Kitty workspace. start creates a separate Kitty instance with a private local socket; list/inspect reconcile exact tagged panes. create launches a direct executable/argv in an owned pane/tab/OS window. focus/resize/layout/detach/close use stable surface IDs and verify observed state. read returns screen text; send_text/send_key target only an owned pane. Closing a pane can terminate its child. Closed views are never recreated automatically."
#define SURFACE_SCHEMA "{\"type\":\"object\",\"properties\":{\"action\":{\"type\":\"string\",\"enum\":[\"status\",\"start\",\"list\",\"inspect\",\"create\",\"focus\",\"resize\",\"layout\",\"detach\",\"read\",\"send_text\",\"send_key\",\"close\"]},\"workspace\":{\"type\":\"string\",\"description\":\"Named workspace, letters/digits/underscore/hyphen, default main.\"},\"surface_id\":{\"type\":\"string\"},\"source_surface_id\":{\"type\":\"string\"},\"request_id\":{\"type\":\"string\",\"description\":\"Create retry identity. A pending launch is reconciled, never blindly replayed.\"},\"run_id\":{\"type\":\"string\"},\"command\":{\"type\":\"string\",\"description\":\"Absolute executable path for start/create, default /bin/sh.\"},\"args\":{\"type\":\"array\",\"items\":{\"type\":\"string\"}},\"type\":{\"type\":\"string\",\"enum\":[\"window\",\"tab\",\"os-window\"]},\"location\":{\"type\":\"string\",\"enum\":[\"split\",\"vsplit\",\"hsplit\"]},\"title\":{\"type\":\"string\"},\"visible\":{\"type\":\"boolean\",\"description\":\"start shows its new OS window; default false (minimized).\"},\"layout\":{\"type\":\"string\",\"enum\":[\"splits\",\"tall\",\"grid\",\"stack\"]},\"axis\":{\"type\":\"string\",\"enum\":[\"horizontal\",\"vertical\",\"reset\"]},\"increment\":{\"type\":\"integer\"},\"text\":{\"type\":\"string\"},\"key\":{\"type\":\"string\"},\"extent\":{\"type\":\"string\",\"enum\":[\"screen\",\"all\",\"last_cmd_output\"]}},\"required\":[\"action\"]}"
bool tool_surface(const char *input, char *result, size_t result_len);
#endif
